// auto-effort: sets Claude Code's effort once per prompt. Jev (TypeSafe's System One model)
// rates how demanding the request is (0-3) at turn.start; the policy in policy.ts smooths that
// into a level, and turn.step sends the turn's model requests at that level. The session's own
// effort setting (/effort, effortLevel) is the ceiling. Subagent loops are left alone, and the
// level never changes inside a turn, so its tool follow-ups keep their prompt cache.
//
// The host reads on(...) and $.noun.method(...) from source, so calls are spelled in full and
// helpers that take $ are top-level functions in this file.
import type { EngineInterface, On } from 'claude-code'

import { DEFAULT_POLICY, type EffortState, LEVELS, decide, levelIndex } from './policy'
import { ENDPOINT, type MessageLike, QUESTIONS, effortState, readJudgment } from './request'
import { DEFAULT_SETTINGS, type Settings, resolveSettings, settingsFiles } from './settings'

const COMMAND = 'auto-effort'

type JevOutcome =
  | { ok: true; judgment: { score: number; confidence: number; ack: number }; latencyMs: number }
  | { ok: false; reason: string }

export function register(on: On): void {
  let settings: Settings = DEFAULT_SETTINGS
  let sessionOn = true
  let state: EffortState = { dwell: DEFAULT_POLICY.minDwell }
  // The level auto-effort set last; undefined before the first prompt.
  let level: string | undefined
  // The session's own effort, read off the main loop's last step: the ceiling.
  let ceiling = 'xhigh'
  let lastReason = ''

  on('session.start', async ($, e, next) => {
    const result = await next(e)
    await $.command.register({
      name: COMMAND,
      description: 'auto-effort: status, on, or off (this session)',
      argumentHint: '[status|on|off]',
      immediate: true,
    })
    return result
  })

  on('turn.start', async ($, e, next) => {
    if (e.text.trim()) settings = await loadSettings($)
    if (sessionOn && settings.enabled && e.text.trim()) {
      const messages = (await $.session.messages()) as readonly MessageLike[]
      const outcome = await askJev($, effortState(e.text, messages), settings)
      const current = level ?? ceiling
      const decision = decide(current, ceiling, state, outcome.ok ? outcome.judgment : undefined, settings.policy)
      state = decision.state
      level = decision.level
      lastReason = outcome.ok ? decision.reason : `unavailable: ${outcome.reason}`
      const detail = outcome.ok
        ? ` (score ${outcome.judgment.score.toFixed(2)}, confidence ${outcome.judgment.confidence.toFixed(2)}, go-ahead ${outcome.judgment.ack.toFixed(2)}, ${outcome.latencyMs} ms)`
        : ''
      $.ui.log(`${current} -> ${level}: ${lastReason}${detail}`, { to: 'debug' })
      $.ui.status(`effort: ${applied(level, ceiling)} (auto)`)
    }
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    // Subagents, a budget instead of a level, and a model without effort pass untouched.
    if (e.agentId !== undefined || typeof e.effort !== 'string' || levelIndex(e.effort) < 0) {
      return yield* next(e)
    }
    ceiling = e.effort
    if (!sessionOn || !settings.enabled || level === undefined) return yield* next(e)
    return yield* next({ ...e, effort: applied(level, ceiling) as (typeof LEVELS)[number] })
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    const arg = e.args.trim()
    if (arg === 'on' || arg === 'off') {
      sessionOn = arg === 'on'
      $.ui.status(sessionOn && settings.enabled && level !== undefined ? `effort: ${applied(level, ceiling)} (auto)` : undefined)
      return { text: `auto-effort ${arg} for this session${sessionOn ? '' : `; back to ${ceiling}`}` }
    }
    const active = sessionOn && settings.enabled
    return {
      text: [
        `auto-effort ${active ? 'on' : settings.enabled ? 'off' : 'off (settings)'}: ${active && level !== undefined ? applied(level, ceiling) : ceiling} now, ceiling ${ceiling} (the session's effort), floor ${settings.policy.floor}.`,
        `Running average ${state.e === undefined ? '-' : state.e.toFixed(2)}, ${state.dwell} prompt${state.dwell === 1 ? '' : 's'} at this level${lastReason ? `, last decision: ${lastReason}` : ''}.`,
      ].join('\n'),
    }
  })
}

/** The level a step is sent at: auto-effort's, never above the session's own. */
function applied(level: string, ceiling: string): string {
  const i = levelIndex(level)
  const c = levelIndex(ceiling)
  return i < 0 || c < 0 || i > c ? ceiling : level
}

/** The shared settings files merged over the defaults (settings.ts); a missing file is skipped. */
async function loadSettings($: EngineInterface): Promise<Settings> {
  const home = (await $.env.get('HOME')) ?? ''
  const xdg = await $.env.get('XDG_CONFIG_HOME')
  const root = await $.session.root()
  const texts: (string | undefined)[] = []
  for (const file of settingsFiles(home, xdg, root)) {
    texts.push(await $.fs.read(file).catch(() => undefined))
  }
  return resolveSettings(texts)
}

/** One System One request. Never throws: every failure is `{ ok: false, reason }`. */
async function askJev($: EngineInterface, jevState: Record<string, unknown>, settings: Settings): Promise<JevOutcome> {
  const key = (await $.env.get('TYPESAFE_API_KEY'))?.trim()
  if (!key) return { ok: false, reason: 'TYPESAFE_API_KEY is not set' }
  const started = Date.now()
  const request = $.http
    .fetch(ENDPOINT, {
      method: 'POST',
      headers: { authorization: `Bearer ${key}`, 'content-type': 'application/json' },
      body: JSON.stringify({ model: settings.jev.model, state: jevState, questions: QUESTIONS }),
    })
    .then(
      (response) => response,
      (error: unknown) => (error instanceof Error ? error.message : String(error)),
    )
  const timeout = $.clock.sleep(settings.jev.timeoutMs).then(() => 'timed out')
  const response = await Promise.race([request, timeout])
  if (typeof response === 'string') return { ok: false, reason: response.slice(0, 160) }
  if (!response.ok) {
    return { ok: false, reason: response.status === 401 ? 'invalid API key' : `HTTP ${response.status}` }
  }
  let body: unknown
  try {
    body = JSON.parse(response.text)
  } catch {
    return { ok: false, reason: 'unreadable response' }
  }
  const judgment = readJudgment(body)
  if (!judgment) return { ok: false, reason: 'response without depth and go-ahead answers' }
  return { ok: true, judgment, latencyMs: Date.now() - started }
}

