// The Jev request for a new prompt: the questions, the state built from the transcript, and
// reading the answers. Pure functions; the HTTP call is in register.ts, where `$` is.

export const ENDPOINT = 'https://api.typesafe.ai/v1/systemone'

export const QUESTIONS = {
  depth: {
    type: 'score',
    instructions:
      'How much careful reasoning does the work asked for in `request` need from a coding agent, given `previous_requests`, `last_outcome` and `signals`?',
    criteria: [
      'A lookup, a trivial answer, or a mechanical change',
      'A routine single-file change or a clear question',
      'A multi-step change, debugging with clear symptoms, or design inside a known pattern',
      'Subtle design, a cross-cutting refactor, hard debugging, or correctness-critical work',
    ],
  },
  ack: {
    type: 'noul',
    instructions:
      'Is `request` a short go-ahead or acknowledgement (like "yes", "go ahead", "continue", "do it") that relies on the plan already discussed, rather than a new task?',
    criteria: { true: 'A go-ahead for work already under way', false: 'A new or changed request' },
  },
} as const

const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])

/** The part of a SessionMessage this reads. */
export interface MessageLike {
  role: 'user' | 'assistant'
  text: string
  toolUses?: readonly { tool: string; isError?: true }[]
  toolResults?: readonly { isError?: true }[]
}

/** The Jev state for a new prompt: the request, the two before it, the last answer, and what the last run did. */
export function effortState(prompt: string, messages: readonly MessageLike[]): Record<string, unknown> {
  // A user message carrying tool results is the engine's, not a prompt.
  const prompts: number[] = []
  messages.forEach((m, i) => {
    if (m.role === 'user' && !m.toolResults?.length && m.text.trim()) prompts.push(i)
  })
  // The new prompt is usually already in the transcript; the previous run is before it.
  const lastPrompt = prompts.at(-1)
  if (lastPrompt !== undefined && messages[lastPrompt]?.text.trim() === prompt.trim()) prompts.pop()
  const runStart = prompts.at(-1)
  const previous = prompts.slice(-2).map((i) => clip(messages[i]?.text.trim() ?? '', 1_000))
  let lastOutcome = ''
  const signals = { last_run_errors: 0, files_edited: 0, tool_calls: 0 }
  if (runStart !== undefined) {
    for (const m of messages.slice(runStart + 1)) {
      if (m.role === 'user') {
        if (!m.toolResults?.length && m.text.trim()) break
        signals.last_run_errors += m.toolResults?.filter((r) => r.isError).length ?? 0
        continue
      }
      if (m.text.trim()) lastOutcome = m.text.trim()
      for (const use of m.toolUses ?? []) {
        signals.tool_calls++
        if (EDIT_TOOLS.has(use.tool) && !use.isError) signals.files_edited++
      }
    }
  }
  return {
    request: clip(prompt, 8_000),
    previous_requests: previous.length ? previous : ['(none: this is the first request)'],
    last_outcome: lastOutcome ? clip(lastOutcome, 1_500) : '(none)',
    signals,
  }
}

/** Depth and go-ahead from a System One response body; undefined when either is missing. */
export function readJudgment(body: unknown): { score: number; confidence: number; ack: number } | undefined {
  const answers = (body as { answers?: Record<string, Record<string, unknown>> } | undefined)?.answers
  const depth = answers?.depth
  const ack = answers?.ack
  if (depth?.type !== 'score' || ack?.type !== 'noul') return undefined
  const score = Number(depth.score)
  const confidence = Number(depth.confidence)
  const yes = Number(ack.noul)
  if (![score, confidence, yes].every(Number.isFinite)) return undefined
  return { score, confidence, ack: yes }
}

export function clip(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, max - 1)}…` : text
}

