// Settings shared with the pi and opencode ports: `~/.config/agents/auto-effort.json` (or under
// $XDG_CONFIG_HOME) and `<project>/.agents/auto-effort.json`, with Claude Code's own
// `~/.claude/auto-effort.json` and `<project>/.claude/auto-effort.json` as overrides. Later files
// win; objects merge, other values replace; keys this port does not know are ignored.
import { DEFAULT_POLICY, type Policy } from './policy'

export const NAME = 'auto-effort'

export interface Settings {
  enabled: boolean
  jev: { model: string; timeoutMs: number }
  policy: Policy
}

export const DEFAULT_SETTINGS: Settings = {
  enabled: true,
  jev: { model: 'jev-latest', timeoutMs: 1_500 },
  policy: DEFAULT_POLICY,
}

/** The settings files, lowest precedence first. */
export function settingsFiles(home: string, xdgConfigHome: string | undefined, root: string): string[] {
  const shared = xdgConfigHome || `${home}/.config`
  return [
    `${shared}/agents/${NAME}.json`,
    `${home}/.claude/${NAME}.json`,
    `${root}/.agents/${NAME}.json`,
    `${root}/.claude/${NAME}.json`,
  ]
}

/** The defaults with each file's JSON merged on top in order; unreadable or invalid text is skipped. */
export function resolveSettings(texts: readonly (string | undefined)[]): Settings {
  let merged: Record<string, unknown> = structuredClone(DEFAULT_SETTINGS) as unknown as Record<string, unknown>
  for (const text of texts) {
    if (text === undefined) continue
    try {
      const value: unknown = JSON.parse(text)
      if (isRecord(value)) merged = merge(merged, value)
    } catch {
      // Invalid JSON: keep what the earlier files said.
    }
  }
  return merged as unknown as Settings
}

function merge(base: Record<string, unknown>, over: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = { ...base }
  for (const [key, value] of Object.entries(over)) {
    const current = out[key]
    out[key] = isRecord(current) && isRecord(value) ? merge(current, value) : value
  }
  return out
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

